INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('2 PROGRAMMES TO BE MERGED – CURRAN IN CAVAN', '2-programmes-to-be-merged-curran-in-cavan', '<p>The announcement was made on Friday (Sept 18th) by Minister of State (MOS) John Curran at a Community and Voluntary Forum conference in Co. Cavan, although details on the plan were not given.</p>
<p>&#8216;Changing Ireland&#8217; has requested an interview with the MOS on questions that arise from the announcement.</p>
<p>In his speech in Cavan, he said:</p>
<p>&#8220;I am seeking improved alignment and focus across the range of programmes for which I have responsibility in the Department of Community, Rural and Gaeltacht Affairs. In this regard, I have been giving particular attention to the redesign of the Local Development Social Inclusion and the Community Development Programmes.</p>
<p>&#8220;I have to say that I am not convinced that two separate programmes and two separate delivery structures is the best way to serve the community. In the current economic climate, the case for a single focussed effective programme is, in my view, indisputable and I will be fighting for resources for the measures covered by the programmes on this basis in the context of the 2010 Budget.&#8221;</p>
<p>An accompanying press release, which described the process in terms of the &#8220;integration&#8221; of the 2 programmes, quoted MOS Curran as saying: “We will continue to do everything we can to improve efficiency and prioritise the provision of frontline services to those who need them the most. One single, focussed programme will ensure that services will be more streamlined and will best serve those who use them.</p>
<p>“We are currently undertaking a thorough review of the Community Development Programme and will shortly have a full report on the findings and recommendations that arise from that review.</p>
<p>“Programme redesign work by the Centre for Effective Services is underway. Overall, we are preparing for a roll-out of a single, redesigned programme in 2010, in the context of the budgetary position.”</p>
<p>John Curran is the Minister of State for the National Drugs Strategy and Community Affairs at the Department of Community, Rural and Gaeltacht Affairs. He is from Clondalkin in Dublin.</p>
<p>&nbsp;</p>', 'The Community Development Programme, first established in 1990, is to be absorbed into a new unnamed programme that also incorporates the Local Development and Social Inclusion Programme.', 'https://changingireland.ie/wp-content/uploads/2009/09/MOS-John-Curran-in-Moyross-2-scaled.jpg', '', '[{"slug":"development-work","title":"Development Work"},{"slug":"funding-programmes","title":"Funding Programmes"},{"slug":"programmes","title":"Programmes"}]', '[{"slug":"centre-for-effective-services","title":"Centre for Effective Services"},{"slug":"community-development-programme","title":"Community Development Programme"},{"slug":"community-development-projects-cdp","title":"community development projects"},{"slug":"john-curran","title":"John Curran"},{"slug":"local-community-development-programme-lcdp","title":"Local and Community Development Programme"},{"slug":"moyross","title":"Moyross"}]', '', 368, 1, '2009-09-22T09:46:00Z', '2020-10-10T13:39:20Z', '2009-09-22T09:46:00Z')
