INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('1200 “positive outcomes” marched against CDP cuts!', '1200-positive-outcomes-marched-against-cdp-cuts', '<p><a href="https://4.bp.blogspot.com/_cgq3tUEQMDo/Sq2H61yxE5I/AAAAAAAAACg/7N1h3vl3JDQ/s1600-h/McCarthy+v+Equality.JPG"><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/Sq2H61yxE5I/AAAAAAAAACg/7N1h3vl3JDQ/s320/McCarthy+v+Equality.JPG" border="0" alt=""id="BLOGGER_PHOTO_ID_5381106574719783826" /></a><br />BY ALLEN MEAGHER, EDITOR<br />If you were there you know the score and well done for standing up for your community, your project and your jobs! <br />If you didn&#8217;t make it, check out these <a href="https://www.indymedia.ie/article/93996?search_text=CDPs">marvellous photos on Indymedia by Paula Geraghty</a> and this<a href="https://www.youtube.com/watch?v=dwrJ7chaga8"> 3 minute video report by &#8216;Changing Ireland&#8217;.</a></p>
<p>The <a href="https://www.nationalcdf.blogspot.com/">National Community Development Forum</a> held a meeting prior to the march and discussed the pressure on volunteers, the latest (CES) review of the Programme and related issues. More details in the next post.</p>
<p>Well done to SIPTU and to everyone involved in the march. Many projects are now starting to engage regionally in lobbying their politicians. The CDP cuts will be raised in Dail questions very shortly and more regional/local protests are on the way.</p>', 'BY ALLEN MEAGHER, EDITORIf you were there you know the score and well done for standing up for your community, your project and your jobs! If you didn’t make it, check out these marvellous photos on Indymedia by Paula Geraghty and this 3 minute video report by ‘Changing Ireland’. The National Community Development Forum held', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 370, 1, '2009-09-13T23:48:00Z', '2009-09-13T23:48:00Z', '2009-09-13T23:48:00Z')
