INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('8 WAYS COMMUNITY GROUPS CAN SAVE MONEY', '8-ways-community-groups-can-save-money', '<p><span>Every tabloid magazine in the known universe has published articles this year about “getting through” the downturn/depression. Here are our ideas for non-profit organisations.<br />More ideas welcome. Please leave your comments/suggestions below:</span><br /><span>1)</span> Instead of paying an organisation for providing a trainer for a day, <span>barter</span> with them and offer a day’s training (in something your group/staff/volunteers are expert in) by way of payment. <br /><span>2) </span>If you’re with the ESB, <span>change</span> electricity supplier and save 10% &#8211; 13% per annum.<br /><span>3) </span>If you’re renting a premises, you can and should <span>negotiate</span> a reduction in rent with your landlord.<br /><span>4)</span> Remember email is <span>free</span>. It wasn’t around a bit over a decade ago.<br /><span>5) </span>You can <span>text</span> for free via the internet (eg www.vodafone.ie). Very handy for getting a message out to a group of people.<br /><span>6)</span> If you need to print something, you’ll save anything up to 20% by going <span>green</span>. ‘Changing Ireland’ changed over to vegetable inks and recycled paper last Autumn.<br /><span>7)</span> Bye-bye to paying people mad money to put a few pages of a website together for your organisation. There are companies nowadays offering <span>ready-to-go websites</span> (the layout is pre-set, you just add in your content) for a tenner a year and upwards. Tip – There are free websites too, but they’re a bit of hassle and very basic. Alternatively, set up a blog (a form of mini-website). It’s totally free and much easier than you think.<br /><span>8)</span> Seek out <span>volunteers</span> to do jobs. You need to support volunteers properly, for it to be beneficial for everyone. Log onto <a href="https://changingireland.blogspot.com/www.boardmatch.ie">www.boardmatch.ie</a> or have a think with your colleagues and make a few calls.</p>
<p><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/SoVAcN0_WwI/AAAAAAAAACI/yiyr3gq7kuI/s1600-h/CI+Volunteers+June+%2709+Ger+and+Breege+FOR+BLOG.JPG"><img decoding="async" src="https://3.bp.blogspot.com/_cgq3tUEQMDo/SoVAcN0_WwI/AAAAAAAAACI/yiyr3gq7kuI/s400/CI+Volunteers+June+%2709+Ger+and+Breege+FOR+BLOG.JPG" border="0" alt=""id="BLOGGER_PHOTO_ID_5369768984201616130" /></a></p>
<p>POST US A COMMENT. YOU CAN BE ANONYMOUS IF YOU PREFER.</p>', 'Every tabloid magazine in the known universe has published articles this year about “getting through” the downturn/depression. Here are our ideas for non-profit organisations.More ideas welcome. Please leave your comments/suggestions below:1) Instead of paying an organisation for providing a trainer for a day, barter with them and offer a day’s training (in something your group/staff/volunteers', '', '', '[{"slug":"community-finance","title":"Community Finance"},{"slug":"funding","title":"Funding"},{"slug":"grants-subsidies","title":"Grants & Subsidies"},{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 373, 1, '2009-08-14T09:32:00Z', '2020-11-20T10:58:07Z', '2009-08-14T09:32:00Z')
