INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Rural Link sees Bord Snip proposals as “sinister”', 'rural-link-sees-bord-snip-proposals-as-sinister', '<p>Irish Rural Link (IRL) has published a 27-page critique of Bord Snip’s “sinister” proposals.<br />The 300-member organisation says one of the report’s main weaknesses is that it “hides the fact that cuts across a number of departments may impact on the same individual.”<br />Two-thirds of Ireland’s poor live in rural Ireland.<br />IRL said Bord Snip showed “disregard” for community groups, adding that “the lack of consideration for the community and voluntary element of work countering social exclusion is one of the most sinister underlying themes.”<br />It drew attention to “ignorance” in the report where it seeks to disband the Department of Community, Rural and Gaeltacht Affairs. As IRL point out, 40% of the population live in rural areas.<br />“The Report (also) fails to acknowledge that community and voluntary organisations deliver essential social services in areas such as education, mental health, disabilities and welfare for very vulnerable people,” say the Westmeath-based organisation.<br />In dissecting the report, IRL cross-tabulate the cuts proposed to various lines of Government spending. One of the most alarming threats to rural communities is to the Rural Transport Programme.<br />IRL’s board is seeking a meeting with the Taoiseach and Minister for Finance as soon as possible.<br />To download the report, visit: <a href="https://changingireland.blogspot.com/www.irishrurallink.ie">www.irishrurallink.ie</a></p>', 'Irish Rural Link (IRL) has published a 27-page critique of Bord Snip’s “sinister” proposals.The 300-member organisation says one of the report’s main weaknesses is that it “hides the fact that cuts across a number of departments may impact on the same individual.”Two-thirds of Ireland’s poor live in rural Ireland.IRL said Bord Snip showed “disregard” for', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 374, 1, '2009-08-12T03:35:00Z', '2009-08-12T03:35:00Z', '2009-08-12T03:35:00Z')
