INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Ireland’s Community spirit never died, report finds – 2 out of 3 regularly engage in volunteering /community activities', 'irelands-community-spirit-never-died-report-finds-2-out-of-3-regularly-engage-in-volunteering-community-activities', '<p><a href="https://1.bp.blogspot.com/_cgq3tUEQMDo/SnLGbKTIsSI/AAAAAAAAACA/frCWnRn99iQ/s1600-h/V+is+for+volunteering.png"><img decoding="async" src="https://1.bp.blogspot.com/_cgq3tUEQMDo/SnLGbKTIsSI/AAAAAAAAACA/frCWnRn99iQ/s320/V+is+for+volunteering.png" border="0" alt=""id="BLOGGER_PHOTO_ID_5364568276075065634" /></a><br />Community spirit is alive and well in Ireland, according to a report by the Central Statistics Office (CSO) that makes minced meat of the widely held view that community spirit and volunteering declined during the boom years.</p>
<p>The report echoes views expressed to ‘Changing Ireland’ last year by a Volunteer Centres Ireland spokesperson saying volunteering had not gone into decline.</p>
<p>The CSO statistics show, on average, almost two-thirds of people in the Republic of Ireland regularly took part in voluntary or community activities.</p>
<p>Nonetheless, there remains a crisis in community participation levels in disadvantaged areas, particularly among those with low education, the unemployed, people in poor health, immigrants and older people. </p>
<p>Irish Times reporter Carl O’Brien lifted the story from the doldrums of a statistical report to give it the front-page treatment. He reports that “community ties seem particularly healthy” and says the CSO figures challenge the belief that the boom years eroded community spirit.</p>
<p>Read Carl’s <a href="https://www.irishtimes.com/newspaper/frontpage/2009/0730/1224251671843.html">main report</a> here, further <a href="https://www.irishtimes.com/newspaper/ireland/2009/0730/1224251670925.html?via=rel">analysis</a> here and the paper’s <a href="https://www.irishtimes.com/newspaper/opinion/2009/0730/1224251669227.html?via=rel">editorial</a> from July 30th.</p>', 'Community spirit is alive and well in Ireland, according to a report by the Central Statistics Office (CSO) that makes minced meat of the widely held view that community spirit and volunteering declined during the boom years. The report echoes views expressed to ‘Changing Ireland’ last year by a Volunteer Centres Ireland spokesperson saying volunteering', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 375, 1, '2009-07-31T09:25:00Z', '2009-07-31T09:25:00Z', '2009-07-31T09:25:00Z')
