INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Galway Travellers Movement want alternatives to evictions', 'galway-travellers-movement-want-alternatives-to-evictions', '<p><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/SlytAmk203I/AAAAAAAAAB4/Hw4LOZgr9GE/s1600-h/GTM+SISTERS.jpg"><img decoding="async" src="https://3.bp.blogspot.com/_cgq3tUEQMDo/SlytAmk203I/AAAAAAAAAB4/Hw4LOZgr9GE/s320/GTM+SISTERS.jpg" alt="" border="0" /></a><br />
As most of Galway celebrated the City&#8217;s arts festival, an Irish Times <a href="https://www.irishtimes.com/newspaper/ireland/2009/0713/1224250544818.html">news report </a>yesterday highlighted the work of one of Galway city&#8217;s CDPs &#8211; the Galway Traveller Movement &#8211; to stand with the community against cultural oppression. While thousands of people planned parties, some families faced eviction.</p>
<p>A report launched two years ago by the Galway Traveller Movement found people were very proud to be Travellers, despite the discrimination they face.</p>
<p>BACKGROUND INFO<br />
We re-publish here a photo (by Derek Speirs) from an exhibition held at that time by Galway Travellers Movement. It features Margaret and Nora Delaney. The full news on the &#8216;Galway Traveller Movement Baseline Report&#8217; launch is available at: https://changingireland.ie/archive.html) Previous &#8216;Changing Ireland&#8217; news reports over the years catalogue the work of the Galway Travellers Movement to stand up with the community against oppression.</p>', 'As most of Galway celebrated the City’s arts festival, an Irish Times news report yesterday highlighted the work of one of Galway city’s CDPs – the Galway Traveller Movement – to stand with the community against cultural oppression. While thousands of people planned parties, some families faced eviction. A report launched two years ago by', '', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"}]', '[{"slug":"travellers","title":"Travellers"}]', '', 376, 1, '2009-07-14T14:57:00Z', '2020-11-20T10:56:32Z', '2009-07-14T14:57:00Z')
