INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Examiner leads with fears by Civil Society groups to protest too loudly', 'examiner-leads-with-fears-by-civil-society-groups-to-protest-too-loudly', '<p><a href="https://4.bp.blogspot.com/_cgq3tUEQMDo/SlMjcBEqDiI/AAAAAAAAABo/EE3jd225O0U/s1600-h/ExaminerleadJuly709.png" target="_blank" rel="noopener noreferrer"><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/SlMjcBEqDiI/AAAAAAAAABo/EE3jd225O0U/s320/ExaminerleadJuly709.png" border="0" alt=""id="BLOGGER_PHOTO_ID_5355663346104929826" /></a></p>
<p>The Irish Examiner&#8217;s lead front page story, in their edition dated Tuesday July 7th, has highlight the fear felt in Civil Society in Ireland &#8211; by groups representing and involving the poor and needy &#8211; to speak up and be heard.<br />To read the story, click <a href="https://www.examiner.ie/home/state-silences-voices-of-poor-and-needy-95756.html">here for the IRISH EXAMINER</a></p>', 'The Irish Examiner’s lead front page story, in their edition dated Tuesday July 7th, has highlight the fear felt in Civil Society in Ireland – by groups representing and involving the poor and needy – to speak up and be heard.To read the story, click here for the IRISH EXAMINER', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 377, 1, '2009-07-07T10:11:00Z', '2009-07-07T10:11:00Z', '2009-07-07T10:11:00Z')
