INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Cutbacks to CE places reversed', 'cutbacks-to-ce-places-reversed', '<p>Volunteers, workers and SIPTU mounted a successful campaign to have cuts to Community Employment Schemes reversed. At a time of rising unemployment, the Schemes need to be expanded if anything. €10m was due to be cut. Thankfully, the CE schemes will survive for now. Read the full story in the <a href="https://www.irishtimes.com/newspaper/ireland/2009/0616/1224248899765.html" target="_blank" rel="noopener noreferrer">Irish Times report</a></p>', 'Volunteers, workers and SIPTU mounted a successful campaign to have cuts to Community Employment Schemes reversed. At a time of rising unemployment, the Schemes need to be expanded if anything. €10m was due to be cut. Thankfully, the CE schemes will survive for now. Read the full story in the Irish Times report', '', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"},{"slug":"funding-programmes","title":"Funding Programmes"},{"slug":"uncategorized","title":"Uncategorized"}]', '[{"slug":"community-employment","title":"Community Employment"}]', '', 378, 1, '2009-06-17T12:24:00Z', '2020-11-20T10:57:38Z', '2009-06-17T12:24:00Z')
