INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Community questions on RTE’s Prime Time', 'community-questions-on-rtes-prime-time', '<p><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/SjjyrccH06I/AAAAAAAAAAs/74HaPIDmcQ4/s1600-h/Community+cutbacks+ruining+lives.jpg"><img decoding="async" src="https://3.bp.blogspot.com/_cgq3tUEQMDo/SjjyrccH06I/AAAAAAAAAAs/74HaPIDmcQ4/s200/Community+cutbacks+ruining+lives.jpg" border="0" alt=""id="BLOGGER_PHOTO_ID_5348291385684906914" /></a><br />David Connolly, Siptu&#8217;s Community Branch President, debated the decline in support for communities from Government with Minister of State John Curran, on June 11th on RTE&#8217;s Prime Time. <a href="https://www.rte.ie/player/#v=1049994" target="_blank" rel="noopener noreferrer">Click here to watch (may require broadband).</a></p>', 'David Connolly, Siptu’s Community Branch President, debated the decline in support for communities from Government with Minister of State John Curran, on June 11th on RTE’s Prime Time. Click here to watch (may require broadband).', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 379, 1, '2009-06-17T12:05:00Z', '2009-06-17T12:05:00Z', '2009-06-17T12:05:00Z')
