INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Welcome to the CHANGING IRELAND BLOG', 'welcome-to-the-changing-ireland-blog', '<p>We&#8217;re glad you could join us!<br />We started adding video to our website this year. Now  <a href="https://changingireland.ie/" target="_blank" rel="noopener noreferrer">Changing Ireland</a> has a blog for news as it happens. <br />Our blog highlights news relating to the Community &#038; Voluntary Sector. We will highlight mainstream media reports, NGO news releases, community-related events and so on. Your comments are welcome.<br />Also, we will post new journalism and original interviews from &#8216;Changing Ireland&#8217; in the blog, prior to publication in &#8216;Changing Ireland&#8217; proper. The print magazine remains a core part of our work as it reaches well over 10,000 readers.</p>
<p>You can subscribe to this blog, to get a notification every time we post a new story.</p>', 'We’re glad you could join us!We started adding video to our website this year. Now Changing Ireland has a blog for news as it happens. Our blog highlights news relating to the Community & Voluntary Sector. We will highlight mainstream media reports, NGO news releases, community-related events and so on. Your comments are welcome.Also, we', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 380, 1, '2009-06-17T09:02:00Z', '2009-06-17T09:02:00Z', '2009-06-17T09:02:00Z')
